import{_ as e,c as t,o as d,a2 as o}from"./chunks/framework.DdOM6S6U.js";const m=JSON.parse('{"title":"Sidebar (ue-sidebar)","description":"","frontmatter":{"sidebarPos":2,"sidebarTitle":"Sidebar"},"headers":[],"relativePath":"guide/components/layouts/sidebar.md","filePath":"guide/components/layouts/sidebar.md","lastUpdated":1777448653000}'),a={name:"guide/components/layouts/sidebar.md"},r=o('<h1 id="sidebar-ue-sidebar" tabindex="-1">Sidebar (<code>ue-sidebar</code>) <a class="header-anchor" href="#sidebar-ue-sidebar" aria-label="Permalink to &quot;Sidebar (`ue-sidebar`)&quot;">​</a></h1><p><code>ue-sidebar</code> is the navigation drawer component. It reads sidebar state from <code>useSidebar()</code> and renders <a href="./sidebar-content"><code>SidebarContent</code></a> either directly or inside a <strong>fully-hidden hover wrapper</strong>, depending on the active display mode.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>You do not use <code>ue-sidebar</code> directly. It is mounted by <a href="./main"><code>ue-main</code></a> via the <code>hideDefaultSidebar</code> prop.</p></div><h2 id="fully-hidden-mode" tabindex="-1">Fully-hidden mode <a class="header-anchor" href="#fully-hidden-mode" aria-label="Permalink to &quot;Fully-hidden mode&quot;">​</a></h2><p>When <code>expandHover</code> is set to <code>&#39;hidden&#39;</code> in <code>ui_settings</code>, the sidebar is completely off-screen. A transparent <strong>hover zone</strong> (12 px wide) sits flush against the left edge of the viewport. On desktop (<code>lgAndUp</code>), hovering over this zone commits <code>CONFIG.SET_SIDEBAR = true</code> to the store, which causes the drawer to slide in.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────────┐</span></span>\n<span class="line"><span>│░  (hover zone, 12px)                         │</span></span>\n<span class="line"><span>│░  ← mouse enters here → sidebar opens        │</span></span>\n<span class="line"><span>└──────────────────────────────────────────────┘</span></span></code></pre></div><p>Moving the mouse outside the wrapper triggers <code>handleSidebarLeave</code>, which closes the drawer again.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table><thead><tr><th>Prop</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>items</code></td><td><code>Array</code></td><td>required</td><td>Navigation items forwarded to <code>ue-navigation-group</code>.</td></tr><tr><td><code>profileMenu</code></td><td><code>Array</code></td><td><code>[]</code></td><td>Profile popover items shown in the sidebar footer.</td></tr><tr><td><code>logoSymbol</code></td><td><code>String</code></td><td><code>&#39;main-logo-dark&#39;</code></td><td>SVG symbol name for the sidebar logo. The mini symbol is resolved automatically via <code>getLocaleSymbol</code>.</td></tr><tr><td><code>rating</code></td><td><code>Number</code></td><td><code>0</code></td><td>Reserved; not currently used in the template.</td></tr></tbody></table><h2 id="slots" tabindex="-1">Slots <a class="header-anchor" href="#slots" aria-label="Permalink to &quot;Slots&quot;">​</a></h2><table><thead><tr><th>Slot</th><th>Description</th></tr></thead><tbody><tr><td><code>bottom</code></td><td>Content appended at the very bottom of the drawer (below the user footer). Passed through to <code>SidebarDrawerContent</code>. Used by <code>ue-main</code> for <code>ue-navigation-group</code> bottom items and <code>ue-impersonate-toolbar</code>.</td></tr></tbody></table><h2 id="exposed-methods" tabindex="-1">Exposed methods <a class="header-anchor" href="#exposed-methods" aria-label="Permalink to &quot;Exposed methods&quot;">​</a></h2><table><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>profileFormSubmitted(res)</code></td><td>Called by <code>ue-main</code> after a profile save; re-fetches the user profile from <code>URLS.profileShow</code>.</td></tr></tbody></table><h2 id="sidebar-state-from-usesidebar" tabindex="-1">Sidebar state (from <code>useSidebar</code>) <a class="header-anchor" href="#sidebar-state-from-usesidebar" aria-label="Permalink to &quot;Sidebar state (from `useSidebar`)&quot;">​</a></h2><p><code>ue-sidebar</code> consumes the following reactive values from <code>useSidebar()</code>. These are not props — they are driven entirely by the store and <code>ui_settings</code>:</p><table><thead><tr><th>Value</th><th>Description</th></tr></thead><tbody><tr><td><code>fullyHidden</code></td><td>Enables the hover-zone wrapper</td></tr><tr><td><code>hoverZoneWidth</code></td><td>Width (px) of the transparent hover strip</td></tr><tr><td><code>status</code></td><td>Whether the drawer is open</td></tr><tr><td><code>rail</code></td><td>Whether the drawer is in icon-only rail mode</td></tr><tr><td><code>isHoverable</code></td><td>Enables Vuetify&#39;s built-in <code>expand-on-hover</code></td></tr><tr><td><code>hideIcons</code></td><td>Hides nav icons (text-only mode)</td></tr><tr><td><code>width</code></td><td>Drawer width in px</td></tr><tr><td><code>effectivePersistent / Permanent / Temporary</code></td><td>Vuetify drawer behaviour props</td></tr><tr><td><code>railManual</code></td><td>Whether the user has manually collapsed to rail</td></tr></tbody></table><h2 id="active-menu" tabindex="-1">Active menu <a class="header-anchor" href="#active-menu" aria-label="Permalink to &quot;Active menu&quot;">​</a></h2><p><code>ue-sidebar</code> provides <code>activeMenu</code> (from <code>useSidebar</code>) to all descendants via Vue&#39;s <code>provide/inject</code> API under the key <code>&#39;activeMenu&#39;</code>. Navigation group items use this to highlight the active route.</p><h2 id="auto-scroll-to-active-item" tabindex="-1">Auto-scroll to active item <a class="header-anchor" href="#auto-scroll-to-active-item" aria-label="Permalink to &quot;Auto-scroll to active item&quot;">​</a></h2><p>On <code>onMounted</code>, the component scrolls <code>.sidebar-item-active</code> into view within <code>.v-navigation-drawer__content</code> using <code>useGoTo</code> with 200 ms easing.</p>',20),i=[r];function s(c,n,h,l,p,u){return d(),t("div",null,i)}const v=e(a,[["render",s]]);export{m as __pageData,v as default};
